def solve_pairing(n):
    """
    Checks if {1, 2, ..., 2n} can be paired such that the differences
    are exactly {1, 2, ..., n}.
    """
    N = 2 * n
    numbers = set(range(1, N + 1))
    required_diffs = set(range(1, n + 1))

    def backtrack(current_numbers, current_diffs, pairs):
        if not current_numbers:
            return True, pairs

        if not current_diffs:
            # Should only happen if current_numbers is also empty
            return False, []

        # Find the smallest remaining number
        a = min(current_numbers)

        # Try pairing 'a' with every other available number 'b'
        for b in current_numbers:
            if a >= b:
                continue

            diff = b - a

            if diff in current_diffs:
                # Try this pairing
                new_numbers = current_numbers - {a, b}
                new_diffs = current_diffs - {diff}

                success, final_pairs = backtrack(new_numbers, new_diffs, pairs + [(a, b)])

                if success:
                    return True, final_pairs

        return False, []

    success, pairs = backtrack(numbers, required_diffs, [])
    return success, pairs

# Test small values
